    const finiteVerbList = ['bin','bist','ist','sind','seid','war','waren','habe','hast','hat','haben','habt','werde','wirst','wird','werden','werdet','muss','musst','müssen','muesse','kann','kannst','können','koennen','soll','sollst','sollen','will','willst','wollen','mag','möchte','moechte','mache','machst','macht','machen','gehe','gehst','geht','gehen','spiele','spielst','spielt','spielen','lerne','lernst','lernt','lernen','esse','isst','essen','trinke','trinkst','trinkt','trinken','wohne','wohnst','wohnt','wohnen','arbeite','arbeitest','arbeitet','arbeiten','finde','findest','findet','lieben','liebe','liebst','liebt','hasse','hasst','hassen'];

    function normalizeText(text) {
      return text
        .toLowerCase()
        .replace(/ä/g, 'a')
        .replace(/ö/g, 'o')
        .replace(/ü/g, 'u')
        .replace(/ß/g, 'ss')
        .replace(/[^a-z0-9\s]/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
    }

    function wordCount(text) {
      const words = text.trim().match(/[A-Za-zÄÖÜäöüß]+(?:-[A-Za-zÄÖÜäöüß]+)*/g);
      return words ? words.length : 0;
    }

    function sentenceList(text) {
      return text
        .split(/(?<=[.!?])\s+/)
        .map(s => s.trim())
        .filter(Boolean);
    }

    function countMatches(text, patternList) {
      return patternList.reduce((total, pattern) => {
        const matches = text.match(pattern);
        return total + (matches ? matches.length : 0);
      }, 0);
    }

    function detectTimeframes(text) {
      const lowered = text.toLowerCase();
      const past = pastMarkers.some(p => p.test(lowered)) ? 1 : 0;
      const future = futureMarkers.some(p => p.test(lowered)) ? 1 : 0;

      let present = 0;
      if (presentMarkers.some(p => p.test(lowered))) {
        present = 1;
      } else if (/\b(ich|wir|man)\b[^.!?]{0,25}\b(bin|habe|mag|spiele|lerne|wohne|esse|trinke|gehe|finde|mache|sehe|treffe|arbeite|nutze|benutze)\b/i.test(text)) {
        present = 1;
      }
      if (!present && wordCount(text) > 20) {
        present = 1;
      }
      return { past, present, future, total: past + present + future };
    }

    function detectComplexity(text) {
      return countMatches(text, complexityPatterns) + Math.min(3, countMatches(text, connectivePatterns));
    }

    function getLexicalVariety(text) {
      const raw = normalizeText(text).split(' ').filter(Boolean);
      const stop = new Set(['ich','du','er','sie','es','wir','ihr','und','aber','oder','denn','weil','wenn','dass','das','der','die','den','dem','des','ein','eine','einen','einem','einer','ist','sind','war','waren','habe','hat','haben','bin','bist','im','in','am','an','auf','zu','mit','für','fur','von','nicht','sehr','auch']);
      const content = raw.filter(w => !stop.has(w) && w.length > 2);
      const unique = new Set(content);
      const ratio = content.length ? unique.size / content.length : 0;
      return { unique: unique.size, contentWords: content.length, ratio };
    }

    function coverageStatus(task, text) {
      const lowered = normalizeText(text);
      return task.checks.map(check => {
        let hitCount = 0;
        for (const group of check.keywords) {
          const groupHit = group.some(keyword => lowered.includes(normalizeText(keyword)));
          if (groupHit) hitCount += 1;
        }
        let status = 'missing';
        if (hitCount >= Math.max(2, Math.ceil(check.keywords.length * 0.6))) status = 'covered';
        else if (hitCount >= 1) status = 'partial';
        return {
          label: check.label,
          status,
          hitCount,
          needed: check.keywords.length,
          timeframe: check.timeframe || null
        };
      });
    }

    function detectAccuracyIssues(text) {
      const issues = [];
      const sentences = sentenceList(text);
      const seen = new Set();

      function addIssue(message, severity = 'minor', category = 'general') {
        const key = `${severity}|${category}|${message}`;
        if (!seen.has(key)) {
          seen.add(key);
          issues.push({ message, severity, category });
        }
      }

      const frontedTimeRegex = /^(gestern|heute|morgen|letztes jahr|letzte woche|letztes wochenende|am samstag|am sonntag|im sommer|im september|nächstes jahr|naechstes jahr)\b/i;
      const finiteVerbRegex = /^(bin|bist|ist|sind|seid|war|waren|habe|hast|hat|haben|habt|werde|wirst|wird|werden|werdet|muss|musst|müssen|muessen|kann|kannst|können|koennen|soll|sollst|sollen|will|willst|wollen|möchte|moechte|mag|spiele|spielst|spielt|spielen|gehe|gehst|geht|gehen|lerne|lernst|lernt|lernen|mache|machst|macht|machen|esse|isst|essen|trinke|trinkst|trinkt|trinken|arbeite|arbeitest|arbeitet|arbeiten|wohne|wohnst|wohnt|wohnen|finde|findest|findet)$/i;

      sentences.forEach((sentence, index) => {
        const trimmed = sentence.trim();
        if (!trimmed) return;

        if (/^[a-zäöü]/.test(trimmed)) {
          addIssue(`Sentence ${index + 1} starts with a lower-case letter.`, 'minor', 'capital');
        }

        if (frontedTimeRegex.test(trimmed) && /^(gestern|heute|morgen|letztes jahr|letzte woche|letztes wochenende|am samstag|am sonntag|im sommer|im september|nächstes jahr|naechstes jahr)\b[^.!?]{0,8}\b(ich|wir|du|er|man)\b/i.test(trimmed)) {
          addIssue('Check word order after a fronted time phrase: the verb should usually come before the subject.', 'major', 'word-order');
        }
      });

      if (/\b(muss|musst|müssen|muessen|kann|kannst|können|koennen|soll|sollst|sollen|will|willst|wollen|möchte|moechte)\b[^.!?]{0,8}\bzu\b[^.!?]{0,16}\b[a-zäöüß]+/i.test(text)) {
        addIssue('After a modal verb, German usually takes the infinitive without "zu".', 'major', 'modal');
      }

      if (/\b(habe|hast|hat|haben|habt|bin|bist|ist|sind|seid)\b[^.!?]{0,24}\b(gehen|spielen|lernen|machen|essen|trinken|arbeiten|kaufen|sehen|treffen|besuchen|schwimmen|wandern|reisen|wohnen)\b/i.test(text)) {
        addIssue('Check whether you need a past participle here instead of an infinitive.', 'major', 'tense');
      }

      const agreementPatterns = [
        [/\bich\b[^.!?]{0,3}\b(spielst|spielt|spielen|gehst|geht|gehen|lernst|lernt|lernen|machst|macht|machen|isst|essen|trinkst|trinkt|trinken|findest|findet|finden|arbeitest|arbeitet|arbeiten|wohnst|wohnt|wohnen|hast|hat|haben|bist|ist|sind|wirst|wird|werden|kannst|kann|können|koennen|musst|muss|müssen|muessen|willst|will|wollen)\b/i, 'Check subject-verb agreement after "ich".'],
        [/\bdu\b[^.!?]{0,3}\b(spiele|spielt|spielen|gehe|geht|gehen|lerne|lernt|lernen|mache|macht|machen|esse|essen|trinke|trinken|finde|findet|finden|arbeite|arbeitet|arbeiten|wohne|wohnt|wohnen|habe|hat|haben|bin|ist|sind|werde|wird|werden|muss|müssen|muessen|kann|können|koennen|will|wollen)\b/i, 'Check subject-verb agreement after "du".'],
        [/\bwir\b[^.!?]{0,3}\b(spiele|spielst|spielt|gehe|gehst|geht|lerne|lernst|lernt|mache|machst|macht|esse|isst|trinke|trinkst|trinkt|finde|findest|findet|arbeite|arbeitest|arbeitet|wohne|wohnst|wohnt|habe|hast|hat|bin|bist|ist|werde|wirst|wird|muss|musst|kann|kannst|will|willst)\b/i, 'Check subject-verb agreement after "wir".'],
        [/\b(er|man)\b[^.!?]{0,3}\b(spiele|spielen|gehe|gehen|lerne|lernen|mache|machen|esse|essen|trinke|trinken|finde|finden|arbeite|arbeiten|wohne|wohnen|habe|haben|bin|sind|werde|werden|müssen|muessen|wollen|können|koennen)\b/i, 'Check subject-verb agreement after a singular subject.']
      ];
      agreementPatterns.forEach(([pattern, message]) => {
        if (pattern.test(text)) addIssue(message, 'major', 'verb');
      });

      const lowered = text.toLowerCase();
      for (const [wrong, right] of commonSpellingIssues) {
        if (lowered.includes(wrong)) {
          addIssue(`Possible spelling issue: "${wrong}" → "${right}".`, 'minor', 'spelling');
        }
      }

      const subPatterns = ['weil','wenn','obwohl','dass','als','da'];
      const tokens = text.toLowerCase().replace(/[^a-zäöüß\s]/g, ' ').split(/\s+/).filter(Boolean);
      tokens.forEach((tok, idx) => {
        if (subPatterns.includes(tok)) {
          const window = tokens.slice(idx + 1, idx + 10);
          const lastTwo = window.slice(-2);
          const finiteInside = window.findIndex(w => finiteVerbList.includes(w));
          const finiteLate = lastTwo.some(w => finiteVerbRegex.test(w) || finiteVerbList.includes(w));
          if (finiteInside !== -1 && !finiteLate && window.length >= 4) {
            addIssue(`Check word order after "${tok}": the finite verb often needs to go to the end.`, 'major', 'word-order');
          }
        }
      });

      return issues.slice(0, 12);
    }

    function getIssueSummary(issues) {
      const major = issues.filter(i => i.severity === 'major').length;
      const minor = issues.filter(i => i.severity === 'minor').length;
      const weighted = (major * 2) + minor;
      const verbRelated = issues.filter(i => ['verb', 'tense', 'modal'].includes(i.category)).length;
      const wordOrder = issues.filter(i => i.category === 'word-order').length;
      return { major, minor, weighted, verbRelated, wordOrder, total: issues.length };
    }

    function getDevelopmentCount(text) {
      const reasons = countMatches(text, [/\bweil\b/gi, /\bdenn\b/gi, /\bdeshalb\b/gi, /\bda\b/gi]);
      const sequencers = countMatches(text, [/\bzuerst\b/gi, /\bdann\b/gi, /\bdanach\b/gi, /\bspäter\b/gi, /\bspaeter\b/gi, /\bschließlich\b/gi, /\bschliesslich\b/gi]);
      const intensifiers = countMatches(text, [/\bsehr\b/gi, /\becht\b/gi, /\bwirklich\b/gi, /\bziemlich\b/gi, /\bbesonders\b/gi]);
      return reasons + sequencers + intensifiers;
    }

    function scoreQ2(task, text, coverage, frames, complexity, variety, issues) {
      const words = wordCount(text);
      const covered = coverage.filter(c => c.status === 'covered').length;
      const partial = coverage.filter(c => c.status === 'partial').length;
      const development = getDevelopmentCount(text);
      const opinionCount = countMatches(text, opinionPatterns);
      const sentenceCount = sentenceList(text).length;
      const summary = getIssueSummary(issues);

      let ao2 = 0;
      if (covered === 3 && words >= 88 && development >= 3 && summary.major <= 1 && summary.weighted <= 4) ao2 = 10;
      else if (covered === 3 && words >= 80 && development >= 2 && summary.major <= 2 && summary.weighted <= 6) ao2 = 9;
      else if (covered === 3 && words >= 72 && development >= 2 && summary.weighted <= 8) ao2 = 8;
      else if (covered === 3 && words >= 65) ao2 = 7;
      else if ((covered >= 2 || (covered === 1 && partial >= 1)) && words >= 62 && development >= 1) ao2 = 6;
      else if ((covered >= 2 || (covered === 1 && partial >= 1)) && words >= 52) ao2 = 5;
      else if ((covered >= 1 || partial >= 1) && words >= 40) ao2 = 4;
      else if ((covered >= 1 || partial >= 1) && words >= 28) ao2 = 3;
      else if ((covered >= 1 || partial >= 1) && words >= 18) ao2 = 2;
      else if (words >= 10) ao2 = 1;

      if (covered < 3) ao2 = Math.min(ao2, 6);
      if (summary.major >= 4 || summary.weighted >= 10) ao2 = Math.min(ao2, 4);
      else if (summary.major >= 3 || summary.weighted >= 8) ao2 = Math.min(ao2, 6);
      else if (summary.major >= 2 || summary.weighted >= 6) ao2 = Math.min(ao2, 8);
      if (sentenceCount < 3 && ao2 > 6) ao2 = 6;

      let ao3 = 0;
      if (frames.total === 3 && variety.unique >= 24 && complexity >= 4 && words >= 80 && opinionCount >= 1 && summary.major <= 1 && summary.weighted <= 4) ao3 = 5;
      else if (frames.total >= 2 && variety.unique >= 18 && complexity >= 2 && words >= 68 && summary.major <= 2 && summary.weighted <= 7) ao3 = 4;
      else if (frames.total >= 2 && variety.unique >= 14 && complexity >= 1 && words >= 58 && summary.weighted <= 10) ao3 = 3;
      else if (variety.unique >= 10 && words >= 45) ao3 = 2;
      else if (words >= 15) ao3 = 1;

      if (summary.major >= 5 || summary.weighted >= 12) ao3 = Math.min(ao3, 1);
      else if (summary.major >= 3 || summary.weighted >= 9) ao3 = Math.min(ao3, 2);
      if (ao2 === 0) ao3 = 0;
      return {
        ao2, ao3,
        total: ao2 + ao3,
        words,
        majorEstimate: summary.major,
        minorEstimate: summary.minor,
        weightedIssues: summary.weighted,
        development
      };
    }

    function scoreQ3(task, text, coverage, frames, complexity, variety, issues) {
      const words = wordCount(text);
      const covered = coverage.filter(c => c.status === 'covered').length;
      const partial = coverage.filter(c => c.status === 'partial').length;
      const development = getDevelopmentCount(text);
      const sentenceCount = sentenceList(text).length;
      const summary = getIssueSummary(issues);

      let ao2 = 0;
      if (covered === 2 && words >= 145 && development >= 4 && sentenceCount >= 5 && summary.major <= 2 && summary.weighted <= 6) ao2 = 15;
      else if (covered === 2 && words >= 135 && development >= 3 && sentenceCount >= 5 && summary.major <= 3 && summary.weighted <= 8) ao2 = 14;
      else if (covered === 2 && words >= 125 && development >= 3 && sentenceCount >= 4 && summary.weighted <= 10) ao2 = 13;
      else if (covered === 2 && words >= 115 && development >= 2) ao2 = 12;
      else if (covered === 2 && words >= 100 && development >= 2) ao2 = 11;
      else if (covered === 2 && words >= 90) ao2 = 10;
      else if ((covered >= 1 && partial >= 1) && words >= 85) ao2 = 9;
      else if ((covered >= 1 && partial >= 1) && words >= 75) ao2 = 8;
      else if (covered >= 1 && words >= 65) ao2 = 7;
      else if ((covered >= 1 || partial >= 1) && words >= 50) ao2 = 6;
      else if ((covered >= 1 || partial >= 1) && words >= 38) ao2 = 5;
      else if ((covered >= 1 || partial >= 1) && words >= 28) ao2 = 4;
      else if (words >= 18) ao2 = 2;
      else if (words >= 8) ao2 = 1;

      if (covered < 2) ao2 = Math.min(ao2, 12);
      if (summary.major >= 6 || summary.weighted >= 14) ao2 = Math.min(ao2, 6);
      else if (summary.major >= 4 || summary.weighted >= 11) ao2 = Math.min(ao2, 9);
      else if (summary.major >= 3 || summary.weighted >= 8) ao2 = Math.min(ao2, 12);

      let range = 0;
      if (variety.unique >= 34 && complexity >= 5 && sentenceCount >= 6 && summary.major <= 2) range = 5;
      else if (variety.unique >= 27 && complexity >= 4 && sentenceCount >= 5 && summary.major <= 3) range = 4;
      else if (variety.unique >= 20 && complexity >= 2 && sentenceCount >= 4) range = 3;
      else if (variety.unique >= 14 && (complexity >= 1 || sentenceCount >= 4)) range = 2;
      else if (words >= 20) range = 1;

      if (summary.major >= 5 || summary.weighted >= 14) range = Math.min(range, 2);
      else if (summary.major >= 3 || summary.weighted >= 10) range = Math.min(range, 3);

      let accuracy = 0;
      if (summary.major <= 1 && summary.minor <= 3 && summary.verbRelated <= 1 && words >= 110) accuracy = 5;
      else if (summary.major <= 3 && summary.minor <= 6 && summary.verbRelated <= 2 && words >= 95) accuracy = 4;
      else if (summary.major <= 5 && summary.minor <= 9 && words >= 75) accuracy = 3;
      else if (words >= 45) accuracy = 2;
      else if (words >= 20) accuracy = 1;

      if (summary.major >= 8 || summary.weighted >= 18) accuracy = 1;
      else if (summary.major >= 6 || summary.weighted >= 13) accuracy = Math.min(accuracy, 2);
      else if (summary.verbRelated >= 3) accuracy = Math.min(accuracy, 3);

      if (ao2 === 0) { range = 0; accuracy = 0; }
      return {
        ao2, range, accuracy,
        total: ao2 + range + accuracy,
        words,
        majorEstimate: summary.major,
        weightedIssues: summary.weighted,
        development
      };
    }

    function bandLabel(task, scores) {
      if (task.question === 'Q2') {
        if (scores.total >= 13) return ['Very strong Q2 response', 'good'];
        if (scores.total >= 10) return ['Secure Q2 response', 'good'];
        if (scores.total >= 7) return ['Developing Q2 response', 'warn'];
        return ['Early-stage Q2 response', 'bad'];
      }
      if (scores.total >= 21) return ['Very strong Q3 response', 'good'];
      if (scores.total >= 16) return ['Secure Q3 response', 'good'];
      if (scores.total >= 11) return ['Developing Q3 response', 'warn'];
      return ['Early-stage Q3 response', 'bad'];
    }

    function reminderText(question) {
      if (question === 'Q2') {
        return 'Q2 reward points: cover all 3 bullet points, aim for roughly 90 words, include all three time frames, and add some complexity such as weil/wenn/obwohl or an um...zu clause.';
      }
      return 'Q3 reward points: cover both bullet points, aim for roughly 150 words, develop ideas in detail, and show range plus accuracy.';
    }

    function helperOpeners(question) {
      if (question === 'Q2') {
        return 'Present: <strong>Normalerweise...</strong>, <strong>Jeden Tag...</strong>, <strong>In meiner Freizeit...</strong><br>Past: <strong>Gestern...</strong>, <strong>Letztes Wochenende...</strong>, <strong>Letztes Jahr habe ich...</strong><br>Future: <strong>Nächstes Jahr...</strong>, <strong>Im September werde ich...</strong>, <strong>Später möchte ich...</strong>';
      }
      return 'Opinions: <strong>Meiner Meinung nach...</strong>, <strong>Ich finde, dass...</strong>, <strong>Ich bin der Meinung, dass...</strong><br>Argument building: <strong>Einerseits...</strong> / <strong>andererseits...</strong>, <strong>Außerdem...</strong>, <strong>Deshalb...</strong><br>Hypothetical ideas: <strong>Ich würde...</strong>, <strong>Das wäre...</strong>, <strong>Wenn ich könnte...</strong>';
    }

    function helperStructures(question) {
      if (question === 'Q2') {
        return 'Try to include at least one <strong>weil</strong> sentence, one clear past reference, and one future idea. Example structure: <strong>Ich spiele...</strong> → <strong>Letztes Wochenende habe ich...</strong> → <strong>Nächstes Jahr werde ich...</strong>';
      }
      return 'For stronger Q3 writing, add development and complexity: <strong>weil / obwohl / wenn / dass</strong>, comparisons like <strong>besser als</strong>, and longer sentences with reasons, details and examples.';
    }

    function renderTask(task) {
      taskQuestion.textContent = task.question === 'Q2' ? 'Question 2' : 'Question 3';
      taskTitle.textContent = task.title;
      taskTheme.textContent = task.theme;
      taskTarget.textContent = `Target: ~${task.wordTarget} words`;
      taskRubric.textContent = task.rubric;
      taskIntro.textContent = task.question === 'Q2'
        ? 'Write one paragraph in German. Try to cover all three bullet points clearly and include present, past and future references.'
        : 'Write a longer response in German. Develop both bullet points in detail and aim for stronger range and accuracy.';
      taskBullets.innerHTML = task.bullets.map(b => `<li>${b}</li>`).join('');
      openersBox.innerHTML = helperOpeners(task.question);
      structuresBox.innerHTML = helperStructures(task.question);
      markingReminder.textContent = reminderText(task.question);
    }

    function getFilteredTasks() {
      const selectedTheme = themeSelect.value;
      return TASKS.filter(t => t.question === currentQuestion && (selectedTheme === 'All topics' || t.theme === selectedTheme));
    }

    function fillThemeSelect() {
      const themes = ['All topics', ...new Set(TASKS.filter(t => t.question === currentQuestion).map(t => t.theme))];
      themeSelect.innerHTML = themes.map(t => `<option value="${t}">${t}</option>`).join('');
    }

    function fillTaskSelect() {
      const filtered = getFilteredTasks();
      taskSelect.innerHTML = filtered.map(t => `<option value="${t.id}">${t.title} — ${t.theme}</option>`).join('');
    }

    function currentTask() {
      const taskId = taskSelect.value;
      return TASKS.find(t => t.id === taskId) || getFilteredTasks()[0];
    }

    function setQuestion(question) {
      currentQuestion = question;
      questionButtons.q2.classList.toggle('active', question === 'Q2');
      questionButtons.q3.classList.toggle('active', question === 'Q3');
      fillThemeSelect();
      fillTaskSelect();
      const task = currentTask();
      if (task) renderTask(task);
      runLiveStats();
      resetFeedback();
    }

    function randomTask() {
      const filtered = getFilteredTasks();
      const picked = filtered[Math.floor(Math.random() * filtered.length)];
      if (!picked) return;
      taskSelect.value = picked.id;
      renderTask(picked);
      resetFeedback();
      runLiveStats();
    }

    function resetFeedback() {
      coverageList.innerHTML = '';
      markGrid.innerHTML = '';
      overallBand.innerHTML = '';
      strengthList.innerHTML = '<li>Analyse your writing to see strengths.</li>';
      targetList.innerHTML = '<li>Analyse your writing to get next steps.</li>';
      languageList.innerHTML = '<li>Time-frame and complexity comments will appear here.</li>';
      accuracyList.innerHTML = '<li>Likely accuracy checks will appear here.</li>';
    }

    function renderCoverage(coverage, task) {
      coverageList.innerHTML = coverage.map((item, index) => {
        const bulletText = task.bullets[index];
        const statusText = item.status === 'covered' ? 'Covered clearly' : item.status === 'partial' ? 'Partly there' : 'Not clear yet';
        return `
          <div class="coverage-item ${item.status}">
            <strong>Bullet ${index + 1}: ${bulletText}</strong>
            <div>${statusText}</div>
          </div>
        `;
      }).join('');
    }

    function markCard(title, score, max) {
      return `
        <div class="mark">
          <span class="mark-title">${title}</span>
          <span class="mark-score">${score} / ${max}</span>
        </div>
      `;
    }

    function runLiveStats() {
      const text = writingBox.value;
      const frames = detectTimeframes(text);
      wordCountEl.textContent = wordCount(text);
      timeframeValue.textContent = `${frames.past} / ${frames.present} / ${frames.future}`;
      complexityValue.textContent = detectComplexity(text);
      const issueSummary = getIssueSummary(detectAccuracyIssues(text));
      issueValue.textContent = `${issueSummary.major}M / ${issueSummary.minor}m`;
    }

    function plannerText(task) {
      const bulletLines = task.bullets.map((b, i) => `Bullet ${i + 1}: ${b}`).join('\n');
      if (task.question === 'Q2') {
        return `Plan\n${bulletLines}\n\nPresent idea:\nPast idea:\nFuture idea:\nReason / opinion phrase:\nComplex phrase to include:\n\nAnswer:\n`;
      }
      return `Plan\n${bulletLines}\n\nMain opinion:\nReason 1:\nReason 2:\nExample:\nFuture / conditional idea:\nComplex phrase to include:\n\nAnswer:\n`;
    }

    function analyse() {
      const task = currentTask();
      const text = writingBox.value.trim();
      if (!task || !text) {
        resetFeedback();
        targetList.innerHTML = '<li>Write something first, then click Analyse my writing.</li>';
        return;
      }

      const coverage = coverageStatus(task, text);
      const frames = detectTimeframes(text);
      const complexity = detectComplexity(text);
      const variety = getLexicalVariety(text);
      const issues = detectAccuracyIssues(text);

      renderCoverage(coverage, task);

      let scores;
      if (task.question === 'Q2') {
        scores = scoreQ2(task, text, coverage, frames, complexity, variety, issues);
        markGrid.innerHTML = markCard('AO2', scores.ao2, 10) + markCard('AO3', scores.ao3, 5) + markCard('Total', scores.total, 15);
      } else {
        scores = scoreQ3(task, text, coverage, frames, complexity, variety, issues);
        markGrid.innerHTML = markCard('AO2', scores.ao2, 15) + markCard('AO3 Range', scores.range, 5) + markCard('AO3 Accuracy', scores.accuracy, 5) + markCard('Total', scores.total, 25);
      }

      const [bandText, bandClass] = bandLabel(task, scores);
      overallBand.innerHTML = `<span class="level ${bandClass}">${bandText}</span>`;

      const strengths = [];
      const targets = [];
      const languageNotes = [];
      const accuracyNotes = [];

      const coveredCount = coverage.filter(c => c.status === 'covered').length;
      if ((task.question === 'Q2' && coveredCount === 3) || (task.question === 'Q3' && coveredCount === 2)) {
        strengths.push('You have addressed all of the compulsory bullet points clearly.');
      } else if (coveredCount >= 1) {
        strengths.push('At least part of the task is clearly covered.');
        targets.push('Make sure every compulsory bullet point is addressed clearly.');
      } else {
        targets.push('Start by answering the exact bullet points more directly.');
      }

      if (task.question === 'Q2') {
        if (frames.total === 3) strengths.push('You have included past, present and future references, which is helpful for a strong Q2 answer.');
        else if (frames.total === 2) {
          strengths.push('You already have two time frames.');
          targets.push('Add one more clear time frame so the response includes past, present and future.');
        } else {
          targets.push('Q2 works best when it includes clear present, past and future references.');
        }
      } else {
        if (frames.total >= 2) strengths.push('You show more than one time frame, which helps create range.');
        else targets.push('Try adding another time frame or a hypothetical idea to widen the response.');
      }

      if (variety.unique >= (task.question === 'Q2' ? 16 : 24)) {
        strengths.push('Your vocabulary is varied enough to sound less repetitive.');
      } else {
        targets.push('Use a wider range of topic vocabulary instead of repeating the same verbs and nouns.');
      }

      if (complexity >= (task.question === 'Q2' ? 2 : 4)) {
        strengths.push('You are attempting some complex language such as linking words or subordinate clauses.');
      } else {
        targets.push('Add more complexity: for example weil, obwohl, wenn, dass, um...zu or a comparison.');
      }

      const words = wordCount(text);
      if (task.question === 'Q2') {
        if (words >= 80 && words <= 120) strengths.push('Your answer is close to the recommended Q2 length.');
        else if (words < 80) targets.push('Write more relevant detail so you are much closer to the recommended 90 words.');
        else targets.push('This is longer than a typical Q2 answer. Make sure everything stays relevant and clear.');
      } else {
        if (words >= 130 && words <= 190) strengths.push('Your answer is close to the recommended Q3 length.');
        else if (words < 130) targets.push('Develop both bullet points more fully so you move much closer to the recommended 150 words.');
        else targets.push('This is longer than a typical Q3 answer. Keep it detailed but focused.');
      }

      languageNotes.push(`Detected time frames: past = ${frames.past}, present = ${frames.present}, future = ${frames.future}.`);
      languageNotes.push(`Detected complex features: ${complexity}.`);
      if (countMatches(text, opinionPatterns) > 0) {
        languageNotes.push('You have included an opinion phrase.');
      } else {
        languageNotes.push('Add an opinion phrase such as "Meiner Meinung nach..." or "Ich finde, dass...".');
      }

      const issueSummary = getIssueSummary(issues);
      if (issues.length === 0) {
        accuracyNotes.push('No obvious high-frequency accuracy warnings were detected.');
      } else {
        accuracyNotes.push(...issues.map(issue => `${issue.severity === 'major' ? 'Major' : 'Minor'}: ${issue.message}`));
      }

      if (issueSummary.wordOrder === 0) {
        strengths.push('No obvious subordinate-clause word-order warning was triggered.');
      }
      if (issues.some(i => i.category === 'modal')) {
        targets.push('Check modal verbs carefully: after a modal verb, the infinitive usually comes without "zu".');
      }
      if (issueSummary.wordOrder > 0) {
        targets.push('Revise word order after weil / wenn / obwohl / dass so the verb goes to the end of the clause.');
      }
      if (issues.some(i => i.category === 'capital')) {
        targets.push('Check sentence starts and capital letters.');
      }
      if (issueSummary.verbRelated >= 2) {
        targets.push('Verbs and tense formations need tighter checking — these carry a lot of weight in the mark scheme.');
      }

      if (targets.length === 0) {
        targets.push('Push the response further with one more developed reason, example or contrast.');
      }
      if (strengths.length === 0) {
        strengths.push('You have made a clear attempt at the task. Now focus on making each idea more precise and accurate.');
      }

      strengthList.innerHTML = strengths.map(i => `<li>${i}</li>`).join('');
      targetList.innerHTML = targets.map(i => `<li>${i}</li>`).join('');
      languageList.innerHTML = languageNotes.map(i => `<li>${i}</li>`).join('');
      accuracyList.innerHTML = accuracyNotes.map(i => `<li>${i}</li>`).join('');

      runLiveStats();
    }

    questionButtons.q2.addEventListener('click', () => setQuestion('Q2'));
    questionButtons.q3.addEventListener('click', () => setQuestion('Q3'));
