    plannerBtn.addEventListener('click', () => {
      const task = currentTask();
      const planner = plannerText(task);
      writingBox.value = planner + writingBox.value;
      writingBox.focus();
      runLiveStats();
    });
    writingBox.addEventListener('input', runLiveStats);

    document.querySelectorAll('.char-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const char = btn.getAttribute('data-char');
        const start = writingBox.selectionStart;
        const end = writingBox.selectionEnd;
        const text = writingBox.value;
        writingBox.value = text.slice(0, start) + char + text.slice(end);
        writingBox.focus();
        writingBox.selectionStart = writingBox.selectionEnd = start + char.length;
        runLiveStats();
      });
    });

